<script setup>
import { computed, ref } from 'vue';
import { Head, router } from '@inertiajs/vue3';
import AppLayout from '../Layouts/AppLayout.vue';

const props = defineProps({ module: String, config: { type: Object, required: true }, records: { type: Array, default: () => [] } });
const config = props.config;
const rows = computed(() => props.records);
const query = ref(''); const activeTab = ref('Resumen'); const modal = ref(false); const detail = ref(null); const toast = ref(''); const formName = ref('');
const shown = computed(() => rows.value.filter((row) => !query.value || row.values.join(' ').toLowerCase().includes(query.value.toLowerCase())));
function notice(message) { toast.value = message; setTimeout(() => toast.value === message && (toast.value = ''), 2500); }
function save() { if (!formName.value.trim()) return notice('Completa el nombre del registro.'); router.post(`/${props.module}`, { name: formName.value }, { preserveScroll: true, onSuccess: () => { formName.value = ''; modal.value = false; notice('Cambios guardados correctamente.'); } }); }
function destroy(row) { router.delete(`/${props.module}/${row.id}`, { preserveScroll: true, onSuccess: () => notice('Registro eliminado.') }); }
function stateClass(value) { return /venc|mora|crít|alto|urgente/i.test(value) ? 'danger' : /vigente|activo|cumpl|pagada|completado|proced/i.test(value) ? 'success' : 'warning'; }
</script>
<template><Head :title="config.title" /><AppLayout><div class="module-page"><div class="module-header"><div><h2>{{ config.icon }} {{ config.title }}</h2><p>Gestión B2G · {{ rows.length }} registros disponibles</p></div><button class="module-primary" @click="modal=true">{{ config.action }}</button></div><div class="module-toolbar"><label>🔍<input v-model="query" :placeholder="`Buscar en ${config.title.toLowerCase()}...`"></label></div><div class="module-table-wrap"><table class="module-table"><thead><tr><th v-for="column in config.columns" :key="column">{{ column }}</th><th>Acciones</th></tr></thead><tbody><tr v-if="!shown.length"><td :colspan="config.columns.length+1" class="module-empty">Sin registros disponibles.</td></tr><tr v-for="row in shown" :key="row.id" @click="detail=row"><td v-for="(value,index) in row.values" :key="index"><span v-if="index === row.values.length-1" class="module-status" :class="stateClass(value)">{{ value }}</span><template v-else>{{ value }}</template></td><td><button class="row-action" @click.stop="detail=row">Ver</button><button class="row-action delete" @click.stop="destroy(row)">Eliminar</button></td></tr></tbody></table></div></div><div v-if="toast" class="quote-toast">{{ toast }}</div><div v-if="modal" class="modal-overlay" @click.self="modal=false"><form class="quote-modal module-form" @submit.prevent="save"><header><div><h3>{{ config.action.replace('+ ', '') }}</h3><p>{{ config.title }}</p></div><button type="button" class="modal-close" @click="modal=false">×</button></header><label>{{ config.columns[0] }} *<input v-model="formName" autofocus></label><footer><button class="module-primary" type="submit">Guardar cambios</button><button type="button" class="quote-cancel" @click="modal=false">Cancelar</button></footer></form></div><div v-if="detail" class="modal-overlay" @click.self="detail=null"><section class="quote-modal module-detail"><header><div><h3>{{ detail.values[0] }}</h3><p>{{ config.title }}</p></div><button class="modal-close" @click="detail=null">×</button></header><dl><template v-for="(column,index) in config.columns" :key="column"><dt>{{ column }}</dt><dd>{{ detail.values[index] }}</dd></template></dl><footer><button class="quote-cancel" @click="detail=null">Cerrar</button></footer></section></div></AppLayout></template>
